describe('Payment Timeout Redirection to Error Page', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should redirect to error page when payment times out', () => {
    // Intercept the payment API call
    cy.intercept('POST', '/api/payment/process', {
      statusCode: 504,
      body: { error: 'Gateway timeout' }
    }).as('paymentTimeout');

    // Fill in payment details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/25');
    cy.get('[data-testid="cvc-input"]').type('123');

    // Click pay button
    cy.get('[data-testid="pay-button"]').click();

    // Wait for the payment API call
    cy.wait('@paymentTimeout');

    // Verify redirection to error page
    cy.url().should('include', '/error');
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Payment timed out');
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });

  it('should display error message and prevent navigation when payment times out', () => {
    // Intercept the payment API call with timeout
    cy.intercept('POST', '/api/payment/process', {
      statusCode: 504,
      body: { error: 'Gateway timeout' }
    }).as('paymentTimeout');

    // Fill in payment details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="expiry-date-input"]').type('12/22');
    cy.get('[data-testid="cvc-input"]').type('123');

    // Click pay button
    cy.get('[data-testid="pay-button"]').click();

    // Wait for the payment API call
    cy.wait('@paymentTimeout');

    // Verify error message is displayed on checkout page
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Payment timed out');

    // Verify user is still on checkout page
    cy.url().should('include', '/checkout');
    cy.get('[data-testid="order-summary"]').should('be.visible');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });
});
